<template>
  <section v-if="instance" class="resource-panel" v-loading="loading"><div class="toolbar"><div><h2>{{t('productResources.pushTitle')}}</h2><p>{{t('productResources.pushDescription')}}</p></div><el-button v-if="canManage" type="primary" @click="openCreate">{{t('productResources.addChannel')}}</el-button></div><el-table :data="channels"><el-table-column prop="name" :label="t('productResources.name')" min-width="140"/><el-table-column prop="type" :label="t('productResources.type')" width="110"/><el-table-column prop="endpoint" :label="t('productResources.endpoint')" min-width="220" show-overflow-tooltip/><el-table-column prop="secretAlias" :label="t('productResources.secretAlias')" min-width="130"/><el-table-column :label="t('productResources.status')" width="90"><template #default="{row}"><el-tag :type="row.enabled?'success':'info'">{{row.enabled?t('productResources.enabled'):t('productResources.disabled')}}</el-tag></template></el-table-column><el-table-column :label="t('productResources.actions')" width="210" fixed="right"><template #default="{row}"><template v-if="canManage"><el-button link @click="edit(row)">{{t('productResources.edit')}}</el-button><el-button link :type="row.enabled?'warning':'primary'" @click="toggle(row)">{{row.enabled?t('productResources.disabled'):t('productResources.enabled')}}</el-button><el-button link type="danger" @click="remove(row)">{{t('productResources.delete')}}</el-button></template></template></el-table-column></el-table><el-empty v-if="!channels.length&&!loading" :description="t('productResources.empty')"/>
    <el-divider/><div class="toolbar"><div><h2>{{t('productResources.deliveryLogs')}}</h2></div></div><el-table :data="deliveries"><el-table-column prop="channelId" :label="t('productResources.key')" min-width="160"/><el-table-column prop="status" :label="t('productResources.status')" width="110"/><el-table-column prop="attemptCount" :label="t('productResources.attempts')" width="80"/><el-table-column prop="error" :label="t('productResources.error')" min-width="180" show-overflow-tooltip/><el-table-column :label="t('productResources.time')" min-width="170"><template #default="{row}">{{new Date(row.createTime).toLocaleString()}}</template></el-table-column></el-table>
    <el-dialog v-model="dialog" :title="editing?t('productResources.edit'):t('productResources.addChannel')" width="520px" destroy-on-close><el-form label-position="top"><el-form-item :label="t('productResources.name')"><el-input v-model="form.name"/></el-form-item><el-form-item v-if="!editing" :label="t('productResources.type')"><el-select v-model="form.type"><el-option label="Webhook" value="webhook"/><el-option label="DingTalk" value="dingtalk"/><el-option label="Feishu" value="feishu"/><el-option label="WeCom" value="wechat_work"/></el-select></el-form-item><el-form-item :label="t('productResources.endpoint')"><el-input v-model="form.endpoint"/></el-form-item><el-form-item :label="t('productResources.secretAlias')"><el-input v-model="form.secretAlias"/></el-form-item></el-form><template #footer><el-button @click="dialog=false">{{t('cancel')}}</el-button><el-button type="primary" @click="save">{{t('productResources.save')}}</el-button></template></el-dialog>
  </section>
</template>
<script setup lang="ts">
import {ref,watch}from 'vue';import {ElMessage,ElMessageBox}from 'element-plus';import type {DeveloperProductInstanceDto,DeveloperPushChannelDto,DeveloperPushDeliveryDto}from '@/client/types.gen';import{developerProductService}from '@/service/developerProductService';import {i18ns} from '@/locales';const {t}=i18ns;const props=defineProps<{instance?:DeveloperProductInstanceDto;canManage:boolean}>();const loading=ref(false),channels=ref<DeveloperPushChannelDto[]>([]),deliveries=ref<DeveloperPushDeliveryDto[]>([]),dialog=ref(false),editing=ref<DeveloperPushChannelDto>(),form=ref({name:'',type:'webhook' as 'webhook'|'dingtalk'|'feishu'|'wechat_work',endpoint:'',secretAlias:''});const load=async()=>{if(!props.instance)return;loading.value=true;try{const [nextChannels,nextDeliveries]=await Promise.all([developerProductService.listPushChannelResources(props.instance.id),developerProductService.listPushDeliveryResources(props.instance.id)]);channels.value=nextChannels;deliveries.value=nextDeliveries}finally{loading.value=false}};const openCreate=()=>{editing.value=undefined;form.value={name:'',type:'webhook',endpoint:'',secretAlias:''};dialog.value=true};const edit=(row:DeveloperPushChannelDto)=>{editing.value=row;form.value={name:row.name,type:row.type as typeof form.value.type,endpoint:row.endpoint,secretAlias:row.secretAlias||''};dialog.value=true};const save=async()=>{if(!props.instance)return;if(editing.value)await developerProductService.updatePushChannelResource(props.instance.id,editing.value.id,{name:form.value.name,endpoint:form.value.endpoint,secretAlias:form.value.secretAlias||null});else await developerProductService.createPushChannelResource(props.instance.id,{...form.value,secretAlias:form.value.secretAlias||undefined});dialog.value=false;await load();ElMessage.success(t('updateSuccess'))};const toggle=async(row:DeveloperPushChannelDto)=>{if(!props.instance)return;await developerProductService.updatePushChannelResource(props.instance.id,row.id,{enabled:!row.enabled});await load()};const remove=async(row:DeveloperPushChannelDto)=>{if(!props.instance)return;await ElMessageBox.confirm(`${t('delete')} ${row.name}?`,t('confirmDelete'),{type:'warning'});await developerProductService.deletePushChannelResource(props.instance.id,row.id);await load();ElMessage.success(t('deleteSuccess'))};watch(()=>props.instance?.id,load,{immediate:true})
</script><style scoped>.toolbar{display:flex;justify-content:space-between;gap:16px;align-items:flex-start;margin-bottom:16px}.toolbar h2{margin:0 0 6px;font-size:17px}.toolbar p{margin:0;color:var(--el-text-color-secondary)}</style>
